namespace sv_b9ea1e15af5749f988c0eeb7d60824b9.Services;

/// <summary>
/// Scoped service (per circuit) that tracks low-stock alert counts
/// and notifies all subscribed components when data changes.
/// </summary>
public class InventoryAlertService : IDisposable
{
    private readonly Random _random = new();
    private Timer? _timer;
    private int _subscriberCount;
    private string? _currentWarehouseId;

    public int LatestAlertCount { get; private set; }

    public event Action? OnChange;

    public Task<int> GetLowStockCountAsync(string warehouseId)
    {
        // Simulate a database query — return random number 0–15.
        var count = _random.Next(0, 16);
        return Task.FromResult(count);
    }

    /// <summary>
    /// Begin polling for the given warehouse. Multiple callers share
    /// one timer; polling stops when the last subscriber leaves.
    /// </summary>
    public void StartPolling(string warehouseId)
    {
        _currentWarehouseId = warehouseId;
        _subscriberCount++;

        if (_timer is null)
        {
            _timer = new Timer(PollCallback, null, TimeSpan.Zero, TimeSpan.FromSeconds(10));
        }
    }

    public void StopPolling()
    {
        _subscriberCount = Math.Max(0, _subscriberCount - 1);

        if (_subscriberCount == 0)
        {
            _timer?.Dispose();
            _timer = null;
        }
    }

    /// <summary>
    /// Called when the warehouse selection changes while polling is active.
    /// </summary>
    public void UpdateWarehouse(string warehouseId)
    {
        _currentWarehouseId = warehouseId;

        if (_timer is not null)
        {
            // Immediately re-poll for the new warehouse.
            _timer.Change(TimeSpan.Zero, TimeSpan.FromSeconds(10));
        }
    }

    private async void PollCallback(object? state)
    {
        if (_currentWarehouseId is null) return;

        LatestAlertCount = await GetLowStockCountAsync(_currentWarehouseId);
        OnChange?.Invoke();
    }

    public void Dispose()
    {
        _timer?.Dispose();
        _timer = null;
    }
}

