@* Interactive dropdown — embedded in the static layout via rendermode *@
@rendermode InteractiveServer
@using sv_b9ea1e15af5749f988c0eeb7d60824b9.Services
@inject CascadingValueSource<WarehouseInfo> WarehouseSource
@inject InventoryAlertService AlertService

<select class="form-select form-select-sm" value="@_selectedId"
        @onchange="OnWarehouseChanged" style="max-width: 200px;">
    @foreach (var wh in WarehouseInfo.AvailableWarehouses)
    {
        <option value="@wh.Key">@wh.Value</option>
    }
</select>

@code {
    private string _selectedId = "WH-A";

    private async Task OnWarehouseChanged(ChangeEventArgs e)
    {
        _selectedId = e.Value?.ToString() ?? "WH-A";
        var name = WarehouseInfo.AvailableWarehouses[_selectedId];

        // Push the new selection to every [CascadingParameter] subscriber.
        await WarehouseSource.NotifyChangedAsync(
            new WarehouseInfo { WarehouseId = _selectedId, Name = name });

        // If polling is active, switch to the new warehouse immediately.
        AlertService.UpdateWarehouse(_selectedId);
    }
}

@* Alert badge — subscribes to InventoryAlertService for live updates *@
@rendermode InteractiveServer
@using sv_b9ea1e15af5749f988c0eeb7d60824b9.Services
@inject InventoryAlertService AlertService
@implements IDisposable

@if (AlertService.LatestAlertCount > 0)
{
    <span class="badge bg-danger rounded-pill ms-2">@AlertService.LatestAlertCount</span>
}
else
{
    <span class="badge bg-success rounded-pill ms-2">0</span>
}

@code {
    private Action? _handler;

    protected override void OnInitialized()
    {
        // The event fires from a Timer (background thread) —
        // wrap StateHasChanged in InvokeAsync so we marshal back
        // to the Blazor synchronization context.
        _handler = () => InvokeAsync(StateHasChanged);
        AlertService.OnChange += _handler;
    }

    public void Dispose()
    {
        AlertService.OnChange -= _handler;
    }
}

@page "/dashboard"
@rendermode InteractiveServer
@using sv_b9ea1e15af5749f988c0eeb7d60824b9.Services
@inject InventoryAlertService AlertService
@implements IDisposable

<PageTitle>Warehouse Dashboard</PageTitle>

<h1>Warehouse Dashboard</h1>

<div class="card mt-3" style="max-width: 400px;">
    <div class="card-body">
        <h5 class="card-title">Current Warehouse</h5>
        <p class="card-text fs-5">
            @if (Warehouse is not null)
            {
                <strong>@Warehouse.Name</strong> <span class="text-muted">(@Warehouse.WarehouseId)</span>
            }
        </p>
    </div>
</div>

<div class="card mt-3" style="max-width: 400px;">
    <div class="card-body">
        <h5 class="card-title">Low-Stock Alerts</h5>
        <p class="card-text fs-3">
            @if (AlertService.LatestAlertCount > 0)
            {
                <span class="text-danger">⚠ @AlertService.LatestAlertCount items below minimum</span>
            }
            else
            {
                <span class="text-success">✓ All stock levels OK</span>
            }
        </p>
        <p class="text-muted small">Refreshes every 10 seconds</p>
    </div>
</div>

@code {
    [CascadingParameter]
    private WarehouseInfo? Warehouse { get; set; }

    private Action? _handler;
    private string? _lastWarehouseId;

    protected override void OnInitialized()
    {
        _handler = () => InvokeAsync(StateHasChanged);
        AlertService.OnChange += _handler;
    }

    protected override void OnParametersSet()
    {
        var whId = Warehouse?.WarehouseId ?? "WH-A";

        if (_lastWarehouseId != whId)
        {
            // Stop any previous polling before starting for the new warehouse.
            if (_lastWarehouseId is not null)
            {
                AlertService.StopPolling();
            }

            _lastWarehouseId = whId;
            AlertService.StartPolling(whId);
        }
    }

    public void Dispose()
    {
        AlertService.OnChange -= _handler;
        AlertService.StopPolling();
    }
}

